const sizeClasses: Record<string, string> = {
  default: "h-8 w-8", // Default size for the icon
  md: "h-6 w-6", // Default size for the icon
  sm: "h-5 w-5", // Smaller size for the icon
  lg: "h-12 w-12", // Larger size for the icon
  xl: "h-16 w-16", // Extra large size for the icon
};

export type ISvgIconComponent = {
  children: React.ReactNode;
  size?: "default" | "sm" | "lg" | "xl" | "md";
  className?: string;
  style?: React.CSSProperties;
  onClick?: () => void;
  viewbox?: string;
};

const SvgIconComponent = ({
  children,
  size = "default",
  className,
  viewbox = "0 0 50 50",
}: ISvgIconComponent) => {
  return (
    <svg
      className={cn(className, sizeClasses[size])}
      xmlns="http://www.w3.org/2000/svg"
      viewBox={viewbox}
    >
      {children}
    </svg>
  );
};



